from packaging.ranges import VersionRange
from packaging.specifiers import SpecifierSet


def intersect_version_ranges(range1: str, range2: str) -> str:
    """Compute the intersection of two version ranges. range1 and range2 are version range specifiers, e.g. ">=1.0", ">1.0,<3.0", "==1.0.0". Returns the intersection as a version range string."""
    try:
        a = SpecifierSet(range1).to_range()
        b = SpecifierSet(range2).to_range()
        result = a.intersection(b)
        return str(result.to_specifier_set())
    except Exception as e:
        raise ValueError(f"Invalid version range operation: {e}") from e

from packaging.specifiers import SpecifierSet


def convert_specifier_set_to_range(specifiers: str) -> str:
    """Convert a specifier set to a version range. specifiers: a string of version specifiers, e.g. '>=1.0,<2.0' -> '>=1.0,<2.0'."""
    try:
        specifier_set = SpecifierSet(specifiers)
        version_range = specifier_set.to_range()
        return str(specifier_set)
    except Exception as e:
        raise ValueError(f"Invalid specifiers: {specifiers!r}") from e
